1. Fetch all departments (paginated) and compute the headcount percentile of each matched candidate's department.
2. Fill the template, save the report and show it.
```python
all_departments = []
skip = 0
while True:
    resp = await hr_get_departments_departments_get(skip=skip, limit=limit)
    items = resp.get("items", [])
    if not items:
        break
    all_departments.extend(items)
    if len(items) < limit:
        break
    skip += limit

departments_by_id = {d["id"]: d for d in all_departments}
headcounts = [d["headcount"] for d in all_departments if d.get("headcount") is not None]


def headcount_percentile(value: int) -> float:
    if not headcounts:
        return 0.0
    return round(sum(1 for h in headcounts if h < value) / len(headcounts) * 100, 1)


candidate_departments = {
    d["name"]: (d["headcount"], headcount_percentile(d["headcount"]))
